:root { color-scheme: light; }
* { box-sizing: border-box; }
body {
  font-family: -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  margin: 0; background: #f4f5f7; color: #1c1e21;
}
.wrap { max-width: 720px; margin: 0 auto; padding: 40px 20px 100px; }
h1 { font-size: 22px; margin: 0 0 4px; }
.sub { color: #65676b; margin: 0 0 28px; font-size: 14px; }

.adder {
  display: flex; gap: 8px; background: #fff; padding: 12px;
  border-radius: 12px; box-shadow: 0 1px 3px rgba(0,0,0,.08);
}
.adder input {
  flex: 1; border: 1px solid #d0d3d8; border-radius: 8px;
  padding: 10px 12px; font-size: 15px;
}
.adder input:focus { outline: 2px solid #2d6cdf; border-color: transparent; }
.adder button {
  border: 0; background: #2d6cdf; color: #fff; font-size: 15px;
  padding: 0 18px; border-radius: 8px; cursor: pointer; font-weight: 600;
}
.adder button:hover { background: #245ac2; }

.notice { display: none; margin-top: 10px; border-radius: 10px; padding: 12px 14px; font-size: 14px; align-items: center; gap: 10px; }
.notice.show { display: flex; }
.notice.warn { background: #fff8e6; border: 1px solid #f0d68a; color: #7a5a00; }
.notice.info { background: #eaf1ff; border: 1px solid #b9cdf5; color: #274b8f; }
.notice .txt { flex: 1; }
.notice button { border: 0; border-radius: 6px; padding: 6px 12px; font-size: 13px; font-weight: 600; cursor: pointer; }
.notice .primary { background: #2d6cdf; color: #fff; }
.notice .ghost { background: transparent; color: inherit; text-decoration: underline; }

.searchbar { position: relative; margin-top: 20px; }
.searchbar input {
  width: 100%; border: 1px solid #d0d3d8; border-radius: 10px;
  padding: 11px 14px 11px 38px; font-size: 15px; background: #fff;
}
.searchbar input:focus { outline: 2px solid #2d6cdf; border-color: transparent; }
.searchbar::before {
  content: '🔍'; position: absolute; left: 12px; top: 50%;
  transform: translateY(-50%); font-size: 14px; opacity: .6;
}

.count { margin: 22px 0 12px; font-size: 13px; color: #65676b; min-height: 16px; }

.list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 8px; }
.list li {
  background: #fff; border-radius: 10px; padding: 12px 14px;
  box-shadow: 0 1px 2px rgba(0,0,0,.06); transition: box-shadow .2s, background .2s;
}
.list li.flash { background: #fff6d8; box-shadow: 0 0 0 2px #f0c419; }

.titlerow { display: flex; align-items: center; gap: 6px; }
.title {
  font-size: 15px; font-weight: 600; color: #2d6cdf; cursor: pointer;
  border-radius: 4px; padding: 1px 3px; margin-left: -3px; text-decoration: none;
}
.title:hover { text-decoration: underline; }
.title.fallback { color: #1c1e21; }
.title mark, .link-url mark { background: #ffe58a; color: inherit; border-radius: 2px; padding: 0 1px; }
.fetching .title { color: #90949c; font-style: italic; cursor: default; }

.badge { font-size: 11px; color: #9a6a00; background: #fff3d6; border-radius: 4px; padding: 1px 6px; font-weight: 600; white-space: nowrap; }

.link-url { font-size: 12px; color: #90949c; word-break: break-all; margin-top: 3px; }

.rowactions { margin-left: auto; display: flex; gap: 2px; }
.iconbtn {
  opacity: 0; border: 0; background: transparent; cursor: pointer;
  font-size: 13px; padding: 3px 6px; border-radius: 6px; color: #65676b;
  transition: opacity .12s;
}
.list li:hover .iconbtn, .list li:focus-within .iconbtn { opacity: 1; }
.iconbtn:hover { background: #eef1f6; }
.iconbtn.trash { color: #b0353a; }
.iconbtn.trash:hover { background: #fbeaea; }

input.edit {
  font-size: 15px; font-weight: 600; border: 1px solid #2d6cdf;
  border-radius: 6px; padding: 4px 6px; width: 100%; font-family: inherit;
}

.empty { background: #fff; border: 1px dashed #d0d3d8; border-radius: 12px; padding: 44px 24px; text-align: center; color: #65676b; }
.empty .big { font-size: 34px; margin-bottom: 10px; }
.empty .head { font-size: 16px; font-weight: 600; color: #1c1e21; margin-bottom: 4px; }
.empty .small { font-size: 13px; }

.toast {
  position: fixed; bottom: 24px; left: 50%; transform: translateX(-50%);
  background: #1c1e21; color: #fff; padding: 10px 12px 10px 16px; border-radius: 8px;
  font-size: 13px; display: flex; align-items: center; gap: 12px;
  opacity: 0; pointer-events: none; transition: opacity .2s; max-width: 90vw;
}
.toast.show { opacity: 1; pointer-events: auto; }
.toast span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.toast button { background: transparent; border: 0; color: #7fb2ff; font-weight: 700; cursor: pointer; font-size: 13px; }

